using System.Collections.Immutable;using Scheduler.Core;
static void Check(bool value,string message){if(!value)throw new Exception(message);}var a=new WorkTask("a","A",10);var b=new WorkTask("b","B",99,Dependencies:["a"]);var c=new TaskCatalog([a,b]);Check(new DependencyGraph(c).TopologicalOrder().SequenceEqual(["a","b"]),"graph");var e=new SchedulerEngine(c,[new DelegateTaskHandler((_,_)=>Task.CompletedTask)]);Check((await e.RunAsync([new Worker("w",["cpu"])] )).SequenceEqual(["a","b"]),"engine");var cache=new LruCache<string,int>(2);cache.Put("a",1);cache.Put("b",2);cache.TryGet("a",out _);cache.Put("c",3);Check(!cache.TryGet("b",out _),"lru");Console.WriteLine("ok");
